<section class="heading"><span class="eyebrow">Ваш выбор</span><h1>Корзина</h1></section>
<?php if (!$summary['items']): ?><section class="empty"><h2>Корзина пока пуста</h2><p>Добавьте товары из каталога.</p><a class="button" href="/catalog">Выбрать товары</a></section><?php else: ?>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>Товар</th><th>Цена</th><th>Количество</th><th>Сумма</th><th>Действие</th></tr></thead><tbody>
<?php foreach ($summary['items'] as $item): ?><tr data-id="<?= $item['product']->id ?>"><td><a href="/product/<?= $item['product']->id ?>"><?= e($item['product']->name) ?></a></td><td><?= money($item['product']->priceCents) ?></td><td><form class="qty-form" method="post" action="/cart/set"><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><input type="hidden" name="product_id" value="<?= $item['product']->id ?>"><input aria-label="Количество <?= e($item['product']->name) ?>" name="qty" type="number" min="1" max="<?= min(99,$item['product']->stock) ?>" value="<?= $item['quantity'] ?>" required><button class="secondary">Обновить</button></form></td><td><?= money($item['subtotal']) ?></td><td><form method="post" action="/cart/remove"><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><input type="hidden" name="product_id" value="<?= $item['product']->id ?>"><button class="secondary">Удалить</button></form></td></tr><?php endforeach ?></tbody></table></div><div class="summary"><span>Товаров: <?= $summary['count'] ?></span><strong class="price" data-total="<?= $summary['total'] ?>">Итого <?= money($summary['total']) ?></strong></div></section><?php endif ?>
